class Vehicle {String number; Vehicle(String n){number=n;} double fee(int h){return h*20;}} class TwoWheeler extends Vehicle {TwoWheeler(String n){super(n);} @Override double fee(int h){return h*10;}} class Car extends Vehicle {Car(String n){super(n);} @Override double fee(int h){return h*30;}} public class Main {public static void main(String[]a){System.out.println(new TwoWheeler("A").fee(2));System.out.println(new Car("B").fee(2));}}
